{"file_path":"src/model.js","content":"/**
 * Node types making up the parsed document tree.
 */

export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

export class TableNode {
  constructor(path) {
    this.path = path
    this.map = new Map()
    this.headerDeclared = false
  }
}

export class ArrayTableNode {
  constructor() {
    this.items = []
  }
}

export class ArrayNode {
  constructor(items) {
    this.items = items
  }
}

export class ScalarNode {
  constructor(kind, value) {
    this.kind = kind
    this.value = value
  }
}

export function cmpCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const n = Math.min(ai.length, bi.length)
  for (let i = 0; i < n; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}
"}

