{"file_path":"src/parser.js","content":"/**
 * Parses a configuration document (as described by the task) into a tree of
 * TableNode / ArrayTableNode / ArrayNode / ScalarNode objects rooted at a
 * single TableNode.
 */

import { ConfError, TableNode, ArrayTableNode, ArrayNode, ScalarNode } from './model.js'

function skipWS(s, i) {
  while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++
  return i
}

function isBlankLine(line) {
  let i = 0
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  if (i >= line.length) return true
  return line[i] === '#' || line[i] === ';'
}

const BARE_NAME_RE = /[A-Za-z0-9_-]/

function parseBasicString(s, i, lineNo) {
  // s[i] === '"'
  i++
  let out = ''
  while (true) {
    if (i >= s.length) throw new ConfError(lineNo, 'unterminated string')
    const c = s[i]
    if (c === '"') {
      i++
      break
    }
    if (c === '\\') {
      i++
      if (i >= s.length) throw new ConfError(lineNo, 'unterminated string')
      const e = s[i]
      if (e === '"') {
        out += '"'
        i++
      } else if (e === '\\') {
        out += '\\'
        i++
      } else if (e === 'n') {
        out += '\n'
        i++
      } else if (e === 't') {
        out += '\t'
        i++
      } else if (e === 'r') {
        out += '\r'
        i++
      } else if (e === '0') {
        out += '\0'
        i++
      } else if (e === 'u') {
        const hex = s.slice(i + 1, i + 5)
        if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          i += 5
        } else {
          throw new ConfError(lineNo, 'invalid escape \\u')
        }
      } else {
        throw new ConfError(lineNo, `invalid escape \\${e}`)
      }
    } else {
      out += c
      i++
    }
  }
  return { value: out, pos: i }
}

function parseLiteralString(s, i, lineNo) {
  // s[i] === "'"
  i++
  const start = i
  while (i < s.length && s[i] !== "'") i++
  if (i >= s.length) throw new ConfError(lineNo, 'unterminated string')
  const value = s.slice(start, i)
  i++
  return { value, pos: i }
}

function parseName(s, i, lineNo) {
  if (i >= s.length) throw new ConfError(lineNo, 'expected a name')
  const c = s[i]
  if (c === '"') {
    const r = parseBasicString(s, i, lineNo)
    return { name: r.value, pos: r.pos }
  }
  if (c === "'") {
    const r = parseLiteralString(s, i, lineNo)
    return { name: r.value, pos: r.pos }
  }
  let j = i
  while (j < s.length && BARE_NAME_RE.test(s[j])) j++
  if (j === i) throw new ConfError(lineNo, 'expected a name')
  return { name: s.slice(i, j), pos: j }
}

function parseDottedName(s, i, lineNo) {
  const names = []
  i = skipWS(s, i)
  const first = parseName(s, i, lineNo)
  names.push(first.name)
  i = first.pos
  while (true) {
    const j = skipWS(s, i)
    if (s[j] === '.') {
      let k = skipWS(s, j + 1)
      const r = parseName(s, k, lineNo)
      names.push(r.name)
      i = r.pos
    } else {
      break
    }
  }
  return { names, pos: i }
}

function readBareword(s, i) {
  let j = i
  while (j < s.length) {
    const c = s[j]
    if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
    j++
  }
  return { word: s.slice(i, j), pos: j }
}

const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const NUM_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function normalizeInteger(word) {
  let sign = ''
  let body = word
  if (body[0] === '+' || body[0] === '-') {
    sign = body[0] === '-' ? '-' : ''
    body = body.slice(1)
  }
  body = body.replace(/_/g, '')
  body = body.replace(/^0+(?=\d)/, '')
  if (body === '0') sign = ''
  return sign + body
}

function navigatePrefix(startTable, names, lineNo) {
  let table = startTable
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    const childPath = table.path.concat([name])
    let child = table.map.get(name)
    if (child === undefined) {
      child = new TableNode(childPath)
      table.map.set(name, child)
    }
    if (child instanceof TableNode) {
      table = child
    } else if (child instanceof ArrayTableNode) {
      table = child.items[child.items.length - 1]
    } else {
      throw new ConfError(lineNo, `${childPath.join('.')} is not a table`)
    }
  }
  return table
}

export function parseDocument(lines) {
  const root = new TableNode([])
  let currentTable = root

  function applyTableHeader(names, lineNo) {
    const table = navigatePrefix(root, names, lineNo)
    const name = names[names.length - 1]
    const path = table.path.concat([name])
    let child = table.map.get(name)
    if (child === undefined) {
      child = new TableNode(path)
      table.map.set(name, child)
    } else if (!(child instanceof TableNode)) {
      throw new ConfError(lineNo, `${path.join('.')} is not a table`)
    }
    if (child.headerDeclared) {
      throw new ConfError(lineNo, `table ${path.join('.')} is defined twice`)
    }
    child.headerDeclared = true
    currentTable = child
  }

  function applyArrayHeader(names, lineNo) {
    const table = navigatePrefix(root, names, lineNo)
    const name = names[names.length - 1]
    const path = table.path.concat([name])
    let child = table.map.get(name)
    if (child === undefined) {
      child = new ArrayTableNode()
      table.map.set(name, child)
    } else if (!(child instanceof ArrayTableNode)) {
      throw new ConfError(lineNo, `${path.join('.')} is not an array of tables`)
    }
    const newTable = new TableNode(path)
    child.items.push(newTable)
    currentTable = newTable
  }

  function parseValue(s, i, lineNo, pathPrefix) {
    i = skipWS(s, i)
    if (i >= s.length) throw new ConfError(lineNo, 'expected a value')
    const c = s[i]
    if (c === '#' || c === ';' || c === ',' || c === ']' || c === '}') {
      throw new ConfError(lineNo, 'expected a value')
    }
    if (c === '"') {
      const r = parseBasicString(s, i, lineNo)
      return { node: new ScalarNode('string', r.value), pos: r.pos }
    }
    if (c === "'") {
      const r = parseLiteralString(s, i, lineNo)
      return { node: new ScalarNode('string', r.value), pos: r.pos }
    }
    if (c === '[') return parseArrayValue(s, i, lineNo, pathPrefix)
    if (c === '{') return parseInlineTable(s, i, lineNo, pathPrefix)

    const { word, pos } = readBareword(s, i)
    if (word === 'true') return { node: new ScalarNode('boolean', true), pos }
    if (word === 'false') return { node: new ScalarNode('boolean', false), pos }
    if (INT_RE.test(word)) {
      return { node: new ScalarNode('integer', normalizeInteger(word)), pos }
    }
    if (NUM_RE.test(word) && /[.eE]/.test(word)) {
      return { node: new ScalarNode('float', Number(word.replace(/_/g, ''))), pos }
    }
    throw new ConfError(lineNo, `invalid value ${word}`)
  }

  function parseArrayValue(s, i, lineNo, pathPrefix) {
    i++ // consume '['
    const items = []
    i = skipWS(s, i)
    if (s[i] === ']') {
      i++
      return { node: new ArrayNode(items), pos: i }
    }
    while (true) {
      const r = parseValue(s, i, lineNo, pathPrefix)
      items.push(r.node)
      i = skipWS(s, r.pos)
      if (i >= s.length) throw new ConfError(lineNo, 'unterminated array')
      if (s[i] === ',') {
        i++
        i = skipWS(s, i)
        if (i < s.length && s[i] === ']') {
          i++
          return { node: new ArrayNode(items), pos: i }
        }
        continue
      }
      if (s[i] === ']') {
        i++
        return { node: new ArrayNode(items), pos: i }
      }
      throw new ConfError(lineNo, 'unterminated array')
    }
  }

  function parseInlineTable(s, i, lineNo, pathPrefix) {
    i++ // consume '{'
    const table = new TableNode(pathPrefix)
    i = skipWS(s, i)
    if (s[i] === '}') {
      i++
      return { node: table, pos: i }
    }
    while (true) {
      const { names, pos } = parseDottedName(s, i, lineNo)
      i = skipWS(s, pos)
      if (s[i] !== '=') throw new ConfError(lineNo, 'expected = in an inline table')
      i++
      i = skipWS(s, i)
      const target = navigatePrefix(table, names, lineNo)
      const finalName = names[names.length - 1]
      const path = target.path.concat([finalName])
      if (target.map.has(finalName)) {
        throw new ConfError(lineNo, `key ${path.join('.')} is defined twice`)
      }
      const r = parseValue(s, i, lineNo, path)
      target.map.set(finalName, r.node)
      i = skipWS(s, r.pos)
      if (i >= s.length) throw new ConfError(lineNo, 'unterminated inline table')
      if (s[i] === ',') {
        i++
        i = skipWS(s, i)
        continue
      }
      if (s[i] === '}') {
        i++
        return { node: table, pos: i }
      }
      throw new ConfError(lineNo, 'unterminated inline table')
    }
  }

  function parseHeaderLine(s, i, lineNo) {
    i++ // consume '['
    let isArray = false
    if (s[i] === '[') {
      isArray = true
      i++
    }
    i = skipWS(s, i)
    const { names, pos } = parseDottedName(s, i, lineNo)
    i = skipWS(s, pos)
    if (s[i] !== ']') throw new ConfError(lineNo, 'unterminated table header')
    i++
    if (isArray) {
      if (s[i] !== ']') throw new ConfError(lineNo, 'unterminated table header')
      i++
    }
    i = skipWS(s, i)
    if (i < s.length && s[i] !== '#' && s[i] !== ';') {
      throw new ConfError(lineNo, 'trailing text after a table header')
    }
    if (isArray) applyArrayHeader(names, lineNo)
    else applyTableHeader(names, lineNo)
  }

  function parseAssignLine(s, i, lineNo) {
    const { names, pos } = parseDottedName(s, i, lineNo)
    i = skipWS(s, pos)
    if (s[i] !== '=') throw new ConfError(lineNo, 'expected key = value')
    i++
    i = skipWS(s, i)
    const table = navigatePrefix(currentTable, names, lineNo)
    const finalName = names[names.length - 1]
    const path = table.path.concat([finalName])
    if (table.map.has(finalName)) {
      throw new ConfError(lineNo, `key ${path.join('.')} is defined twice`)
    }
    const r = parseValue(s, i, lineNo, path)
    i = skipWS(s, r.pos)
    if (i < s.length && s[i] !== '#' && s[i] !== ';') {
      throw new ConfError(lineNo, 'trailing text after a value')
    }
    table.map.set(finalName, r.node)
  }

  for (let idx = 0; idx < lines.length; idx++) {
    const line = lines[idx]
    const lineNo = idx + 1
    if (isBlankLine(line)) continue
    const i = skipWS(line, 0)
    if (line[i] === '[') {
      parseHeaderLine(line, i, lineNo)
    } else {
      parseAssignLine(line, i, lineNo)
    }
  }

  return root
}
"}

