 * Renders the parsed document tree as canonical JSON, or as a flat list of
 * paths and types.
 */

import { TableNode, ArrayTableNode, ArrayNode, cmpCodePoint } from './model.js'

function sortedKeys(table) {
  return [...table.map.keys()].sort(cmpCodePoint)
}

function serialize(node, ind) {
  const pad = '  '.repeat(ind)
  const pad1 = '  '.repeat(ind + 1)
  if (node instanceof TableNode) {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const parts = keys.map(
      (k) => `${pad1}${JSON.stringify(k)}: ${serialize(node.map.get(k), ind + 1)}`
    )
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
  if (node instanceof ArrayTableNode) {
    if (node.items.length === 0) return '[]'
    const parts = node.items.map((it) => `${pad1}${serialize(it, ind + 1)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  if (node instanceof ArrayNode) {
    if (node.items.length === 0) return '[]'
    const parts = node.items.map((it) => `${pad1}${serialize(it, ind + 1)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  switch (node.kind) {
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown scalar kind ${node.kind}`)
  }
}

export function renderJSON(root) {
  return serialize(root, 0) + '\n'
}

function typeOf(node) {
  if (node instanceof TableNode) return 'table'
  if (node instanceof ArrayTableNode) return 'array'
  if (node instanceof ArrayNode) return 'array'
  return node.kind
}

export function renderKeys(root) {
  const out = []
  function visit(node, path) {
    out.push(`${path} ${typeOf(node)}`)
    if (node instanceof TableNode) {
      for (const k of sortedKeys(node)) visit(node.map.get(k), `${path}.${k}`)
    } else if (node instanceof ArrayTableNode || node instanceof ArrayNode) {
      node.items.forEach((item, i) => visit(item, `${path}[${i}]`))
    }
  }
  for (const k of sortedKeys(root)) visit(root.map.get(k), k)
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
"}

