{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import fs from 'node:fs'
import { ConfError } from './model.js'
import { parseDocument } from './parser.js'
import { renderJSON, renderKeys } from './render.js'

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let root
  try {
    root = parseDocument(lines)
  } catch (e) {
    if (e instanceof ConfError) {
      process.stderr.write(`error: line ${e.line}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  const output = mode === 'json' ? renderJSON(root) : renderKeys(root)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

